        "properties": {},
    },
    "research": {
        "x-dir": "research",
        "x-prefix": "r",
        "x-numbered": True,
        "properties": {},
    },
}


@pytest.fixture
def vault(tmp_path: Path, monkeypatch):
    """Create a minimal vault, chdir into it, clear registered kinds."""
    root = tmp_path / "vault"
    (root / ".openstation").mkdir(parents=True)
    types_dir = root / "openstation" / "types"
    types_dir.mkdir(parents=True)

    for name, schema in _KINDS.items():
        (types_dir / f"{name}.json").write_text(json.dumps(schema))
        kind_dir = schema["x-dir"]
        (root / "openstation" / kind_dir).mkdir(parents=True, exist_ok=True)

    # Reset globally registered kinds so tests are isolated
    monkeypatch.setattr("artifacts_os.cli._registered_kinds", [])
    monkeypatch.chdir(root)
    return root


@pytest.fixture
def write_artifact():
    """Helper fixture: write a markdown artifact file to the vault."""
    from artifacts_os.core import frontmatter as _frontmatter

    def _write(root: Path, kind_dir: str, filename: str, fm: dict, body: str = "") -> Path:
        path = root / "openstation" / kind_dir / filename
        path.write_text(_frontmatter.dump(fm, body))
        return path

    return _write

"""ID generation and slug utilities.

Spec: s2060-artifacts-os-architecture § ids.py
"""

import re
from pathlib import Path


_SLUG_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")


def next_prefixed_id(directory: Path, prefix: str) -> str:
    """Return next prefixed ID in directory. `{prefix}0001` when empty."""
    directory = Path(directory)
    pattern = re.compile(rf"^{re.escape(prefix)}(\d+)-")
    max_n = 0
    if directory.is_dir():
        for path in directory.glob("*.md"):
            match = pattern.match(path.stem)
            if match:
                n = int(match.group(1))
                if n > max_n:
                    max_n = n
    return f"{prefix}{max_n + 1:04d}"


def slugify(text: str, max_words: int = 5) -> str:
    """Lowercase, collapse non-[a-z0-9] runs to hyphens, take first max_words."""
    lowered = text.lower()
    collapsed = re.sub(r"[^a-z0-9]+", "-", lowered).strip("-")
    if not collapsed:
        return ""
    parts = collapsed.split("-")
    return "-".join(parts[:max_words])


def validate_slug(slug: str) -> bool:
    """Return True iff slug matches ^[a-z0-9]+(-[a-z0-9]+)*$."""
    return bool(_SLUG_RE.match(slug))

